import{z as l,x as A,o as r,c as d,q as i,j as t,D as e,d as n,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"恢复与不恢复除法","description":"","frontmatter":{"title":"恢复与不恢复除法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/restoring-division.md","filePath":"cs/restoring-division.md","lastUpdated":1791063341000}'),B={name:"cs/restoring-division.md"};function D(p,a,c,m,h,_){const E=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="恢复与不恢复除法" tabindex="-1">恢复与不恢复除法 <a class="header-anchor" href="#恢复与不恢复除法" aria-label="Permalink to &quot;恢复与不恢复除法&quot;">​</a></h1><div class="epigraph"><p>除法是乘法的逆：每步试减，够则商 1，不够则商 0；不够时要不要把减回去，分开两种数据通路。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/wallace-carry-save">上一课</a>把乘法收成部分积压缩加一次 CLA。乘是多操作数加；除没有对称的「部分商树」可一次铺开（商的每一位依赖前一位试减结果）。缺口是：<strong>整数除</strong>的移位–减循环，以及恢复与不恢复两种写法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无符号 \\(N\\div D\\)：余数寄存器初始化为 \\(N\\)（或高位置 0），每步左移，减 \\(D\\)。若结果非负，商位移 1，余数采用减法结果；若为负，商位移 0——恢复除法把 \\(D\\) 加回去，不恢复除法则留下负余数、下一步改加 \\(D\\)（因为多减了一次）。缺口不是再定义商与余，而是电路：同一套加法器，\\(c_0\\) 与 \\(B\\) 反相在加/减之间切换。</p><p>本课钉移位减。SRT 用冗余商数字加速，是下一课的缺口。</p><h3 id="恢复不是「软件里-if-再加回去」的另一套语义" tabindex="-1">恢复不是「软件里 if 再加回去」的另一套语义 <a class="header-anchor" href="#恢复不是「软件里-if-再加回去」的另一套语义" aria-label="Permalink to &quot;恢复不是「软件里 if 再加回去」的另一套语义&quot;">​</a></h3><p>两种算法算出同一无符号商与非负余数（最后一步不恢复法若余数为负须加回 \\(D\\)）。差别是中间余数是否允许为负、加法器每拍是否多一次加。把它们当成两种不同的除法定义，后课 SRT 的冗余数字会对不齐。</p><p><span class="marginnote">Harris 用恢复/不恢复对照。Patterson/Hennessy 把除法延迟写成 \\(\\Theta(n)\\) 拍，与组合乘对照。Ercegovac and Lang, <em>Digital Arithmetic</em> 是算术单元的系统参考，本课范围停在这两种经典迭代。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>寄存器：余数 \\(R\\)（可 \\(2n\\) 位）、除数 \\(D\\)、商 \\(Q\\)。每拍：\\(R\\leftarrow 2R\\)，试 \\(R-D\\)。恢复：负则 \\(R\\leftarrow R+D\\)，商比特 0。不恢复：负则下一步做 \\(R+D\\)，正则继续 \\(R-D\\)，商比特为符号的反。\\(n\\) 拍后得到 \\(n\\) 位商。补码有符号除要先处理符号或改用非恢复的符号规则，本课以无符号钉通路。</p><p><span class="marginnote">数字实例：\\(7 \\div 2\\)，用 4 位走一轮。初值 \\(R=0111\\)，左移成 \\(1110\\) 后试减 \\(2\\)（\\(0010\\)）得 \\(1100\\)——高位是 1 说明结果为负（本该够减的假设错了），恢复除法立刻加回 \\(0010\\) 变回 \\(1110\\)、商记 0；不恢复除法则带着这个负的 \\(1100\\) 进入下一拍，只是下一拍改做加法。两条路最终的商都是 \\(0011\\)（3）、余数 \\(0001\\)（1）。</span></p><p><span class="marginnote">直觉类比：试减像猜价格——先大胆喊一个低了的价（左移一位等于把商位挤出来），发现喊多了就恢复法「当场收回去」，不恢复法「先赊着、下一轮多还一点」。两者账本结果一致，差别只是中间欠条允不允许出现。</span></p>',13)),(r(),t(o,null,{default:e(()=>[s(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ND%5B%22%E8%A2%AB%E9%99%A4%E6%95%B0%E4%B8%8E%E9%99%A4%E6%95%B0%22%5D%20--%3E%20SHIFT%5B%22%E5%B7%A6%E7%A7%BB%E4%BD%99%E6%95%B0%22%5D%0A%20%20SHIFT%20--%3E%20TRY%5B%22%E8%AF%95%E5%87%8F%22%5D%0A%20%20TRY%20--%3E%20REST%5B%22%E8%B4%9F%E5%88%99%E5%8A%A0%E5%9B%9E%EF%BC%9A%E6%81%A2%E5%A4%8D%22%5D%0A%20%20TRY%20--%3E%20NREST%5B%22%E8%B4%9F%E5%88%99%E7%95%99%E4%B8%8B%EF%BC%9A%E4%B8%8D%E6%81%A2%E5%A4%8D%22%5D%0A%20%20REST%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ASRT%22%5D%0A%20%20NREST%20--%3E%20LATER%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>与<a href="/cs/array-multiplier">阵列乘法</a>对照：乘可组合树；除的每位商有循环进位依赖，教学实现几乎总是多周期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RV32M 的 <code>div</code>/<code>rem</code> 可以走这条迭代单元，与 <code>mul</code> 分时同一加法器或分单元。除零与溢出（有符号最小负数除 \\(-1\\)）是 ISA 规定的结果或旗标，本课承认要检测，不把陷阱入口写进算术单元。余数符号随被除数的约定（向零截断 vs 向负无穷）是语言/ISA 选择，硬件按选定的恒等式收尾。</p>',3)),(r(),t(o,null,{default:e(()=>[s(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E7%AC%AC%20i%20%E6%8B%8D%22%5D%20--%3E%20SUB%5B%22%E8%AF%95%20R%20-%20D%22%5D%0A%20%20SUB%20--%3E%20Q1%7B%22%E7%BB%93%E6%9E%9C%E7%AC%A6%E5%8F%B7%3F%22%7D%0A%20%20Q1%20--%20%22%E9%9D%9E%E8%B4%9F%22%20--%3E%20P%5B%22%E5%95%86%E4%BD%8D%3D1%2C%20%E4%BD%99%E6%95%B0%3D%E5%B7%AE%2C%20%E4%B8%8B%E4%B8%80%E6%8B%8D%E7%BB%A7%E7%BB%AD%E5%87%8F%22%5D%0A%20%20Q1%20--%20%22%E8%B4%9F%22%20--%3E%20Q2%7B%22%E5%93%AA%E6%9D%A1%E9%80%9A%E8%B7%AF%3F%22%7D%0A%20%20Q2%20--%20%22%E6%81%A2%E5%A4%8D%22%20--%3E%20A1%5B%22%E6%9C%AC%E6%8B%8D%E5%8A%A0%E5%9B%9E%20D%2C%20%E5%95%86%E4%BD%8D%3D0%22%5D%0A%20%20Q2%20--%20%22%E4%B8%8D%E6%81%A2%E5%A4%8D%22%20--%3E%20A2%5B%22%E4%BD%99%E6%95%B0%E7%95%99%E8%B4%9F%E5%80%BC%2C%20%E4%B8%8B%E4%B8%80%E6%8B%8D%E6%94%B9%E5%8A%A0%20D%22%5D%0A%20%20A1%20--%3E%20N%5B%22%E7%AC%AC%20i%2B1%20%E6%8B%8D%22%5D%0A%20%20A2%20--%3E%20N%0A%20%20P%20--%3E%20N%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p>这张图回答的问题是「同一拍上恢复与不恢复的分岔点在哪」：分岔只出现在试减结果为负的那一刻——恢复法当场用一次额外加法「抹掉这一拍」，不恢复法把补偿挪到下一拍的加减选择里。\\(n\\) 拍的总量相差最多 \\(n\\) 次加法，结果恒等。</p><p><span class="marginnote">为什么重要：恢复法的最坏情形每拍要做两次加法（减了再加回），时钟周期或拍数因此变长；不恢复法保证每拍恰好一次加法——代价是控制逻辑要记住「上一拍欠着账」。这就是真实硬件除法器几乎都选非恢复或 SRT 路线的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入商数字集 \\(\\{\\bar 1,0,1\\}\\)，不讲 Goldschmidt/Newton 迭代。也不把浮点除的对阶与规格化画进来。阵列除法器存在，面积与 \\(n^2\\) 级，组成课通常不采用。</p><p>后课默认：整数除是移位–试减；\\(n\\) 拍量级；恢复与不恢复只改中间余数与加减选择。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>乘法已能一棵树压完；除法每位商依赖试减，走迭代。</li><li>恢复：不够则加回；不恢复：负余数用下一步加法补偿。</li><li>除零与有符号溢出按 ISA 收，不在本课展开陷阱。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)；Ercegovac and Lang, <em>Digital Arithmetic</em>。</li></ul>',7))])}const u=l(B,[["render",D]]);export{f as __pageData,u as default};
